# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.32.0/ankra-cli-darwin-arm64"
      sha256 "f65fdac54173bf75ef263b21cbd3cf8a1371c55f12518bdb3098bbd2f6e1fa5e"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.32.0/ankra-cli-darwin-amd64"
      sha256 "6a8271acd40ea6191b9adc4906a5d1222a42ef0fe997416975131201b3156c5c"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.32.0/ankra-cli-linux-arm64"
      sha256 "76106c4e362319d423ef1e63a306cac9f0e8dc1ca4c00db38870985fd5601e5b"
    end
    on_intel do
